-  font: 14px/1.45 -apple-system, "Segoe UI", sans-serif; color: var(--rv-fg); }
-@media (prefers-color-scheme: dark) {
-  #rv-root { --rv-fg: #e4e4e7; --rv-muted: #8b8b94; --rv-bg: #1c1c22; --rv-line: #33333c; --rv-accent: #818cf8; --rv-soft: #26262e; --rv-warn: #fbbf24; --rv-ok: #4ade80; }
-}
-
-#rv-toggle { position: fixed; right: 1rem; bottom: 1rem; z-index: 9999; width: 3rem; height: 3rem;
-  border-radius: 50%; border: 1px solid var(--rv-line); background: var(--rv-accent); color: #fff;
-  font-size: 1.1rem; cursor: pointer; box-shadow: 0 4px 14px rgba(0,0,0,.25); }
-#rv-count { position: absolute; top: -4px; right: -4px; min-width: 1.15rem; height: 1.15rem; border-radius: 99px;
-  background: var(--rv-warn); color: #fff; font-size: .7rem; line-height: 1.15rem; padding: 0 .2rem; display: none; }
-
-#rv-panel { position: fixed; top: 0; right: 0; bottom: 0; z-index: 9998; width: min(360px, 92vw);
-  background: var(--rv-bg); border-left: 1px solid var(--rv-line); box-shadow: -8px 0 24px rgba(0,0,0,.12);
-  display: none; flex-direction: column; }
-#rv-root.rv-open #rv-panel { display: flex; }
-#rv-root.rv-open #rv-toggle { right: calc(min(360px, 92vw) + 1rem); }
-
-#rv-panel header { padding: .9rem 1rem .7rem; border-bottom: 1px solid var(--rv-line); }
-#rv-panel header .rv-sub { color: var(--rv-muted); font-size: .8rem; margin-top: .15rem; }
-#rv-panel header a { color: var(--rv-accent); text-decoration: none; }
-#rv-body { flex: 1; overflow-y: auto; padding: .75rem 1rem; }
-
