-
-.rv-h { font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; color: var(--rv-muted); margin: 1rem 0 .4rem; }
-.rv-empty { color: var(--rv-muted); font-size: .85rem; }
-
-.rv-item { border: 1px solid var(--rv-line); border-radius: 8px; padding: .55rem .65rem; margin-bottom: .5rem; background: var(--rv-soft); }
-.rv-item .rv-anchor { font-size: .78rem; color: var(--rv-accent); cursor: pointer; font-weight: 600; }
-.rv-item .rv-quote { display: block; color: var(--rv-muted); font-style: italic; font-size: .8rem;
-  border-left: 2px solid var(--rv-line); padding-left: .5rem; margin: .3rem 0; }
-.rv-item textarea { width: 100%; box-sizing: border-box; border: 1px solid var(--rv-line); border-radius: 6px;
-  background: var(--rv-bg); color: var(--rv-fg); font: inherit; font-size: .85rem; padding: .4rem .5rem; margin-top: .3rem; resize: vertical; min-height: 3em; }
-.rv-item .rv-remove { float: right; border: 0; background: none; color: var(--rv-muted); cursor: pointer; font-size: .9rem; }
-.rv-item .rv-text { font-size: .85rem; margin-top: .25rem; white-space: pre-wrap; }
-.rv-item .rv-note { font-size: .8rem; color: var(--rv-muted); margin-top: .3rem; padding-left: .5rem; border-left: 2px solid var(--rv-accent); white-space: pre-wrap; }
-
-.rv-round { margin-bottom: .9rem; }
-.rv-round .rv-roundhead { font-size: .8rem; color: var(--rv-muted); margin-bottom: .35rem; }
-.rv-badge { display: inline-block; font-size: .68rem; text-transform: uppercase; letter-spacing: .04em;
-  border-radius: 99px; padding: .05rem .5rem; border: 1px solid var(--rv-line); color: var(--rv-muted); }
-.rv-badge.rv-changed { color: var(--rv-accent); border-color: currentColor; }
-.rv-badge.rv-kept { color: var(--rv-muted); border-color: currentColor; }
-.rv-badge.rv-orphaned { color: var(--rv-warn); border-color: currentColor; }
-.rv-badge.rv-pending { opacity: .7; }
-.rv-badge.rv-verdict-approve, .rv-badge.rv-verdict-approve_with_nits { color: var(--rv-ok); border-color: currentColor; }
-.rv-badge.rv-verdict-request_changes { color: var(--rv-warn); border-color: currentColor; }
-
-#rv-verdicts { padding: .75rem 1rem; border-top: 1px solid var(--rv-line); display: flex; gap: .5rem; }
-#rv-verdicts button { flex: 1; padding: .5rem .25rem; border-radius: 8px; border: 1px solid var(--rv-line);
-  background: var(--rv-soft); color: var(--rv-fg); font: inherit; font-size: .8rem; cursor: pointer; }
-#rv-verdicts button:disabled { opacity: .4; cursor: not-allowed; }
-#rv-approve { background: var(--rv-accent); border-color: var(--rv-accent); color: #fff; }
-
-#rv-chip { position: absolute; z-index: 9997; display: none; border: 1px solid var(--rv-line); border-radius: 99px;
-  background: var(--rv-bg); color: var(--rv-accent); font: 600 .78rem/1 -apple-system, "Segoe UI", sans-serif;
-  padding: .35rem .65rem; cursor: pointer; box-shadow: 0 2px 8px rgba(0,0,0,.18); }
-#rv-chip:hover { background: var(--rv-accent); color: #fff; }
-
-#rv-modal { position: fixed; inset: 0; z-index: 10000; display: none; align-items: center; justify-content: center;
-  background: rgba(0,0,0,.45); }
-#rv-modal .rv-dialog { background: var(--rv-bg); color: var(--rv-fg); border: 1px solid var(--rv-line);
-  border-radius: 12px; padding: 1.25rem 1.4rem; max-width: 22rem; font-size: .9rem; }
-#rv-modal .rv-dialog h3 { margin: 0 0 .5rem; font-size: 1rem; }
-#rv-modal .rv-actions { display: flex; gap: .5rem; margin-top: 1rem; justify-content: flex-end; }
-#rv-modal .rv-actions button { padding: .45rem .9rem; border-radius: 8px; border: 1px solid var(--rv-line);
-  background: var(--rv-soft); color: var(--rv-fg); font: inherit; font-size: .85rem; cursor: pointer; }
-#rv-modal .rv-actions .rv-confirm { background: var(--rv-accent); border-color: var(--rv-accent); color: #fff; }
-
-.rv-hoverable { outline: 2px dashed color-mix(in srgb, currentColor 25%, transparent); outline-offset: 4px; border-radius: 4px; }
-.rv-annotated { box-shadow: -3px 0 0 0 var(--rv-accent); }
-.rv-flash { animation: rv-flash 1.2s ease-out; }
-@keyframes rv-flash { 0% { background: color-mix(in srgb, #818cf8 30%, transparent); } 100% { background: transparent; } }

